action.mutation:
mutation CreateMaintenanceSchedule($payload: [MaintenanceScheduleCreatePayloadInput!]!) {
        mutation: createMaintenanceSchedule(payload: $payload) { 
          id
          number
      }
    }

mutation UpdateMaintenanceSchedule($payload: [MaintenanceScheduleUpdatePayloadInput!]!) {
        mutation: updateMaintenanceSchedule(payload: $payload) { 
          id
          number
      }
    }

mutation DeleteMaintenanceSchedule($payload: [MaintenanceScheduleDeletePayloadInput!]!) {
        mutation: deleteMaintenanceSchedule(payload: $payload) { 
          id
          number
      }
    }
